-- ==========================================================================================
-- This procedure was automatically generated by Insikt Studio.
-- Any edits can and will be overwritten.
-- ==========================================================================================
create procedure [dbo].[ETL_Fact_Resultat_Planning_Import]
(
	@Type nvarchar(4000) = null
	,@ParamList nvarchar(4000) = null	
	,@ParentEventID int = null
	,@PlanningVersionID int = null
)
as
--
-- Standardvariabler
--
declare @ProcName sysname, @TranCount int, @EventIDStack varbinary(max)
set @ProcName = app.GetObjectFullName(@@procid)
set @TranCount = @@trancount


begin try
	--------------------------------------------------------------------------
	-- Start
	--------------------------------------------------------------------------
	exec app.LogEventStart @ParentEventID = @ParentEventID, @EventIDStack = @EventIDStack output, @EventObject = @ProcName
			,@EventTitle = 'ETL Planning import: ETL_Fact_Resultat_Planning_Import'
			,@Description = 'Imports planning data (budget)'

	 
	
	select
		PlanningVersionID
		,FiscalYear
		,[Type]
		,SourceNo = pv.Attribute3
	into
		#PlanningVersion
	from
		dw.dim_PlanningVersion pv
	where
		pv.FCVersionCategoryID = -1
		and (pv.PlanningVersionID = @PlanningVersionID or @PlanningVersionID is null)
	
	
	--------------------------------------------------------------------------
	-- Ta bort alla planeringsversioner som importeras fr�n visma
	--------------------------------------------------------------------------		
	delete from dw.fact_Resultat_Planning
	where 
		ExistsInWriteTable = 0 
		and PlanningVersionID in (select PlanningVersionID from #PlanningVersion)
	
	
		
	INSERT INTO [dw].[fact_Resultat_Planning]
	(
		[PlanningVersionID]
		,[PostingDateID]			
		,[Organisation_LeafID]
	
		,[AvdelningID] 
		,[KampanjID] 
		,[ProjektID] 
		,[VarugruppID] 
		,[KontoID] 
				
		,[PlanningAmount]
		,[PlanningQuantity]
		,[AuditUser]
		,[AuditTime]
		,[ExistsInWriteTable]
		,[IncUpdate]
		,[RowTypeID]
	)
	select
		[PlanningVersionID] = pv.PlanningVersionID
		,[PostingDateID] = dtime.DateID --year(pv.ActDate) * 10000 + month(pv.ActDate) * 100 + day(pv.ActDate)'
		,[Organisation_LeafID] = isnull(dimOrg.[Organisation_LeafID], 0)
			
		,[AvdelningID] = isnull([Avdelning].[AvdelningID], -16)
		,[KampanjID] = isnull([Kampanj].[KampanjID], -12)
		,[ProjektID] = isnull([Projekt].[ProjektID], -15)
		,[VarugruppID] = isnull([Varugrupp].[VarugruppID], -13)
		,[KontoID] = isnull([Konto].[KontoID], -1)
		
			
		,[PlanningAmount] = f.CrInvoAm - f.DbIncCst
		--,[PlanningQuantity] = f.CrInvoAm - f.DbIncCst
		-- TODO
		,[PlanningQuantity] = null
		,[AuditUser] = 'Visma import'
		,[AuditTime] = getdate()
		,[ExistsInWriteTable] = 0
		,[IncUpdate] = 0
		,[RowTypeID] = 101	-- Planering - Resultat				
	from
		#PlanningVersion pv
			inner join [INSIKT_KUND_SA].visma.BgtLn f on
				f.BgNo = pv.SourceNo
				and f.yr = pv.FiscalYear
			left join [dw].[base_Avdelning] [Avdelning] on
				[Avdelning].Code = f.[R1]	
			left join [dw].[base_Kampanj] [Kampanj] on
				[Kampanj].Code = f.[R6]	
			left join [dw].[base_Projekt] [Projekt] on
				[Projekt].Code = f.[R2]	
			left join [dw].[base_Varugrupp] [Varugrupp] on
				[Varugrupp].Code = f.[R4]	
			left join [dw].[base_Konto] [Konto] on
				[Konto].Code = f.[AcNo]	
			left join dw.dim_Organisation dimOrg on
				dimOrg.[AvdelningID] = isnull([Avdelning].[AvdelningID], -16)
			left join [dw].[dim_time] dtime on
				pv.FiscalYear = dtime.year
				and dtime.Day = 1
				and f.pr = dtime.FiscalPeriod
			
			inner join dw.dim_Resultatkonto r on Konto.KontoID = r.KontoID -- Filtrera bort balanskonton
		
	drop table #PlanningVersion
	

	exec app.LogEventStop @EventIDStack = @EventIDStack out
	--------------------------------------------------------------------------
	-- Stop
	--------------------------------------------------------------------------
end try
begin catch	
	--
	-- Roll back any transactions and log errors
	--
	if @TranCount = 0 and @@trancount > 0 rollback tran
	exec app.HandleProcError @EventIDStack out, @ParentEventID, @ProcName
	exec app.ReThrowError
end catch

GO
